action.code:
if (p->position.y <= h)
{
    // Calculate penetration depth
    float penetration = h - p->position.y;

    // Update position to be just above the ground
    p->position.y = h + BOX_COLLISION_OFFSET;

    // Apply elastic bounce to velocity
    p->velocity.y = -p->velocity.y * elasticity;

    // Optional: Add a small upward velocity to prevent sticking
    p->velocity.y += 0.1f;
}

